// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title EventRegistry - On-chain event logging with metadata
 * @notice Stores structured event metadata for off-chain indexers
 * @dev Events are emitted with RFC-5322 style headers for indexer consumption
 */
contract EventRegistry {

    enum Role { NONE, REPORTER, ADMIN }

    mapping(address => Role) public roles;
    mapping(bytes32 => bool) public processedEvents;

    address public owner;
    uint256 public eventNonce;

    // Structured log entry consumed by off-chain HTTP-based indexers
    event MetadataLog(address indexed reporter, string headerBlock);
    event RoleChanged(address indexed account, Role newRole);

    modifier onlyAdmin() {
        require(roles[msg.sender] == Role.ADMIN || msg.sender == owner, "Not admin");
        _;
    }

    modifier onlyReporter() {
        require(
            roles[msg.sender] == Role.REPORTER || 
            roles[msg.sender] == Role.ADMIN || 
            msg.sender == owner,
            "Not reporter"
        );
        _;
    }

    constructor() {
        owner = msg.sender;
        roles[msg.sender] = Role.ADMIN;
    }

    function grantRole(address account, Role role) external onlyAdmin {
        require(account != address(0), "Zero address");
        roles[account] = role;
        emit RoleChanged(account, role);
    }

    function revokeRole(address account) external onlyAdmin {
        roles[account] = Role.NONE;
        emit RoleChanged(account, Role.NONE);
    }

    /**
     * @notice Validates that a field value contains no control characters
     * @dev Checks for bytes that could break header parsing in indexers
     * @param value The string bytes to validate
     * @return True if the value is safe for header inclusion
     */
    function _isCleanFieldValue(bytes memory value) internal pure returns (bool) {
        for (uint256 i = 0; i < value.length; i++) {
            bytes1 ch = value[i];
            // Block NULL bytes, CR, LF, and other dangerous control chars
            if (ch == 0x00 || ch == 0x08 || ch == 0x0a || ch == 0x0b || ch == 0x0c || ch == 0x0d || ch == 0x7f) {
                return false;
            }
        }
        return true;
    }

    /**
     * @notice Sanitizes a field by encoding problematic characters
     * @dev Replaces CR and LF with safe representations
     * @param input Raw input bytes
     * @return Sanitized bytes safe for header inclusion
     */
    function _sanitizeField(bytes memory input) internal pure returns (bytes memory) {
        // Count output length first
        uint256 outLen = 0;
        for (uint256 i = 0; i < input.length; i++) {
            bytes1 ch = input[i];
            if (ch == 0x0d) { // CR
                outLen += 4; // \x0d -> "[CR]"
            } else if (ch == 0x0a) { // LF  
                outLen += 4; // \x0a -> "[LF]"
            } else {
                outLen += 1;
            }
        }

        bytes memory output = new bytes(outLen);
        uint256 j = 0;
        for (uint256 i = 0; i < input.length; i++) {
            bytes1 ch = input[i];
            if (ch == 0x0d) {
                output[j++] = "[";
                output[j++] = "C";
                output[j++] = "R";
                output[j++] = "]";
            } else if (ch == 0x0a) {
                output[j++] = "[";
                output[j++] = "L";
                output[j++] = "F";
                output[j++] = "]";
            } else {
                output[j++] = ch;
            }
        }
        return output;
    }

    /**
     * @notice Submit a structured event with metadata headers
     * @dev The headerBlock is formatted as RFC-5322 headers for indexer parsing
     * @param category Event category identifier
     * @param description Human-readable event description  
     * @param extraField Additional metadata field (user-controlled)
     */
    function submitEvent(
        string calldata category,
        string calldata description,
        string calldata extraField
    ) external onlyReporter {
        bytes memory catBytes = bytes(category);
        bytes memory descBytes = bytes(description);
        bytes memory extraBytes = bytes(extraField);

        require(catBytes.length > 0 && catBytes.length <= 64, "Invalid category");
        require(descBytes.length > 0 && descBytes.length <= 256, "Invalid description");
        require(extraBytes.length <= 512, "Extra field too long");

        // Validate category and description are clean
        require(_isCleanFieldValue(catBytes), "Category contains control chars");
        require(_isCleanFieldValue(descBytes), "Description contains control chars");

        // Sanitize the extra field since it's more free-form
        bytes memory sanitizedExtra = _sanitizeField(extraBytes);

        eventNonce++;

        // Build RFC-5322 style header block for off-chain indexer
        // Format: "Header-Name: value\r\nHeader-Name: value\r\n"
        string memory headerBlock = string(
            abi.encodePacked(
                "X-Event-Nonce: ", _uint2str(eventNonce), "\r\n",
                "X-Reporter: ", _addr2str(msg.sender), "\r\n",
                "X-Category: ", category, "\r\n",
                "X-Description: ", description, "\r\n",
                "X-Extra: ", string(sanitizedExtra), "\r\n"
            )
        );

        emit MetadataLog(msg.sender, headerBlock);
    }

    /**
     * @notice Submit a priority event with full sanitization
     * @dev Admins still get full input validation for defense in depth
     * @param category Event category
     * @param description Event description
     * @param priorityNote Priority annotation
     */
    function submitPriorityEvent(
        string calldata category,
        string calldata description,
        string calldata priorityNote
    ) external onlyAdmin {
        bytes memory catBytes = bytes(category);
        bytes memory descBytes = bytes(description);
        bytes memory noteBytes = bytes(priorityNote);

        require(catBytes.length > 0 && catBytes.length <= 64, "Invalid category");
        require(descBytes.length > 0 && descBytes.length <= 256, "Invalid description");
        require(noteBytes.length <= 256, "Priority note too long");
        require(_isCleanFieldValue(catBytes), "Category contains control chars");
        require(_isCleanFieldValue(descBytes), "Description contains control chars");
        require(_isCleanFieldValue(noteBytes), "Priority note contains control chars");

        eventNonce++;

        string memory headerBlock = string(
            abi.encodePacked(
                "X-Priority: HIGH\r\n",
                "X-Event-Nonce: ", _uint2str(eventNonce), "\r\n",
                "X-Reporter: ", _addr2str(msg.sender), "\r\n",
                "X-Category: ", category, "\r\n",
                "X-Description: ", description, "\r\n",
                "X-Priority-Note: ", priorityNote, "\r\n"
            )
        );

        emit MetadataLog(msg.sender, headerBlock);
    }

    function _uint2str(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) { digits++; temp /= 10; }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits--;
            buffer[digits] = bytes1(uint8(48 + value % 10));
            value /= 10;
        }
        return string(buffer);
    }

    function _addr2str(address addr) internal pure returns (string memory) {
        bytes memory s = new bytes(42);
        s[0] = "0";
        s[1] = "x";
        for (uint256 i = 0; i < 20; i++) {
            bytes1 b = bytes1(uint8(uint160(addr) / (2**(8*(19 - i)))));
            bytes1 hi = bytes1(uint8(b) / 16);
            bytes1 lo = bytes1(uint8(b) - 16 * uint8(hi));
            s[2+i*2] = _hexChar(hi);
            s[3+i*2] = _hexChar(lo);
        }
        return string(s);
    }

    function _hexChar(bytes1 b) internal pure returns (bytes1) {
        if (uint8(b) < 10) return bytes1(uint8(b) + 0x30);
        else return bytes1(uint8(b) + 0x57);
    }
}
